import { type PuzzleContentProps } from "@hunt/domain";
import {
  AuthorsNote,
  FlavorText,
  ImageGallery,
  PostHuntDetails,
  PuzzleInfoBox,
} from "@hunt/puzzle-components";
import { ButtonSecondary, TextInput } from "@hunt/styled-ui";
import React, { useState } from "react";
import infinite_loophole from "./assets/infinite_loophole.png";
import puzzle_dactylinion from "./assets/puzzle_dactylinion.png";
import puzzle_dukdukgoop from "./assets/puzzle_dukdukgoop.png";
import puzzle_featherbrain from "./assets/puzzle_featherbrain.png";
import puzzle_hepanchart from "./assets/puzzle_hepanchart.png";
import puzzle_humidefta from "./assets/puzzle_humidefta.png";
import puzzle_kneedle from "./assets/puzzle_kneedle.png";
import puzzle_knightbulb from "./assets/puzzle_knightbulb.png";
import puzzle_perkepsu from "./assets/puzzle_perkepsu.png";
import puzzle_pointdexter from "./assets/puzzle_pointdexter.png";
import puzzle_sheriff_shaffour from "./assets/puzzle_sheriff_shaffour.png";
import puzzle_steve from "./assets/puzzle_steve.png";
import puzzle_ttattell from "./assets/puzzle_ttattell.png";

const PUZZMON_ANSWERS: Record<string, string[]> = {
  Dactylinion: ["1986/6/22"],
  Dukdukgoop: ["'26 Dec 25", "2026/12/25", "26/12/25"],
  Featherbrain: ["☕"],
  Hepanchart: ["LIFE UNDER THE SUN"],
  Humidefta: ["NEWBIES"],
  Kneedle: ["🕯️"],
  Knightbulb: ["IT'S LIT"],
  Perkepsu: ["PINK"],
  Pointdexter: ["WATER"],
  "Sheriff Shaffour": ["YELLOW"],
  Steve: ["1"],
  Ttattell: ["15"],
};

const LocalAnswerChecker = ({ puzzmon }: { puzzmon: string }) => {
  const [value, setValue] = useState("");
  const [result, setResult] = useState<"correct" | "incorrect" | null>(null);

  const check = () => {
    const normalize = (s: string) =>
      s
        .toUpperCase()
        .replace(/\s/g, "")
        .replace(/^['/]+|['/]+$/g, "");
    const normalized = normalize(value);
    const correctAnswers = PUZZMON_ANSWERS[puzzmon].map(normalize);
    if (correctAnswers.includes(normalized)) {
      setResult("correct");
    } else {
      setResult("incorrect");
    }
  };

  return (
    <form
      className="flex items-center gap-2 mb-4"
      onSubmit={(e) => {
        e.preventDefault();
        check();
      }}
    >
      <div className="w-40 font-bold">{puzzmon}:</div>
      <TextInput
        value={value}
        onChange={(e) => {
          setValue(e.target.value);
          setResult(null);
        }}
        placeholder="Enter answer"
        className="flex-grow"
      />
      <ButtonSecondary type="submit">Check</ButtonSecondary>
      {result === "correct" && (
        <span className="text-green-600 font-bold ml-2">Correct!</span>
      )}
      {result === "incorrect" && (
        <span className="text-red-600 font-bold ml-2">Incorrect</span>
      )}
    </form>
  );
};

type PuzzleProps = Pick<PuzzleContentProps, "teamState">;

const Puzzle = ({ teamState }: PuzzleProps) => {
  const isArchival = teamState.gates_satisfied.includes("archival_mode");
  return (
    <div id="puzzle-content-root">
      {isArchival && (
        <AuthorsNote>
          This finale included an in-person runaround. The archival site
          provides the original materials and local answer checkers below; the
          live interaction is no longer available.
        </AuthorsNote>
      )}
      <FlavorText>
        Congratulations on proving yourselves to the 7 Keepers, unifying the
        Kingdom of the Puzzmon, and discovering the secrets of the artifacts!
      </FlavorText>
      <PuzzleInfoBox copyable={true}>
        Please wait for a phone call to schedule your final mission. Bring at
        least one laptop (although more than one may be useful), as well as pens
        or pencils and something to write on (e.g. clipboards). It is also
        recommended to connect your mobile device to campus wifi before
        departing. There will be some walking involved but you will not need to
        go outside.
      </PuzzleInfoBox>
      <PostHuntDetails>
        <p>
          Members of hunt staff went to the team&apos;s headquarters to inform
          them that a potent{" "}
          <span className="bg-black text-black hover:bg-transparent hover:text-inherit transition-colors cursor-default">
            INFINITE LOOPHOLE
          </span>{" "}
          had been discovered somewhere on campus. The team was shown the
          following photo and asked if they knew where it was on campus.
        </p>
        <br />
        <a href={infinite_loophole} target="_blank" rel="noopener noreferrer">
          <img src={infinite_loophole} alt="Infinite Loophole" />
        </a>
        <br />
        <p>
          After identifying the photo as part of{" "}
          <a
            href="http://borderline.mit.edu/"
            target="_blank"
            rel="noopener noreferrer"
          >
            The Borderline
          </a>{" "}
          exhibit in the MIT tunnels below Building 66, the team was taken to
          the location. At The Borderline, teams were informed that this part of
          the puzzle was constructed by the Keeper of Creation and the Keeper of
          Mysteries. They sent Puzzmon into different universes and created
          puzzles that resolve to the different data types found in Terminus —
          two of each data type. Teams had to use the murals in The Borderline
          to complete all 12 puzzles below. The answers were checked by a member
          of the hunt staff. Once the team had all 12 answers, they were told
          that they could proceed to the final room to close the portal. Images
          of the 12 Borderline puzzles and answer checkers can be found below.
        </p>
        <p>
          When they arrived at the final room, they were told to submit
          LET&apos;S CLOSE THIS PORTAL as the answer to this puzzle to unlock
          the remainder of the final puzzle.
        </p>
        <ImageGallery
          images={[
            { src: puzzle_dactylinion, alt: "Dactylinion Puzzle" },
            { src: puzzle_dukdukgoop, alt: "Dukdukgoop Puzzle" },
            { src: puzzle_featherbrain, alt: "Featherbrain Puzzle" },
            { src: puzzle_hepanchart, alt: "Hepanchart Puzzle" },
            { src: puzzle_humidefta, alt: "Humidefta Puzzle" },
            { src: puzzle_kneedle, alt: "Kneedle Puzzle" },
            { src: puzzle_knightbulb, alt: "Knightbulb Puzzle" },
            { src: puzzle_perkepsu, alt: "Perkepsu Puzzle" },
            { src: puzzle_pointdexter, alt: "Pointdexter Puzzle" },
            { src: puzzle_sheriff_shaffour, alt: "Sheriff Shaffour Puzzle" },
            { src: puzzle_steve, alt: "Steve Puzzle" },
            { src: puzzle_ttattell, alt: "Ttattell Puzzle" },
          ]}
        />
        <div className="mt-8 max-w-2xl mx-auto">
          <h3 className="text-xl font-bold mb-4 border-b-2 border-gray-200 pb-2">
            Puzzmon Mural Puzzle Answer Checkers
          </h3>
          {Object.keys(PUZZMON_ANSWERS).map((puzzmon) => (
            <LocalAnswerChecker key={puzzmon} puzzmon={puzzmon} />
          ))}
        </div>
      </PostHuntDetails>
    </div>
  );
};

export default Puzzle;
