import { type TeamHuntState } from "@hunt/public-client";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import Puzzle from "./puzzle";

const elem = document.getElementById("puzzle-content-root");
if (elem) {
  const { initialTeamState } = window as unknown as {
    initialTeamState?: TeamHuntState;
  };
  if (!initialTeamState) {
    console.error(
      "Could not mount Puzzle because initialTeamState was not found.",
    );
  } else {
    hydrateRoot(elem, <Puzzle teamState={initialTeamState} />);
  }
} else {
  console.error(
    "Could not mount Puzzle because #puzzle-content-root was nowhere to be found",
  );
}
